with slate as materialized(select run_id from forge_runs where git_sha='989ee767cb9723bcf1b9d2242343aee53c7e3448' and status='succeeded' and created_at between '2026-11-23 10:16Z' and '2026-11-23 10:39Z'), teamsched as (select g.id game_id, v.team,v.opp,row_number() over(partition by v.team order by g."startTime",g.id) h from games g cross join lateral (values(g."homeTeamId",g."awayTeamId"),(g."awayTeamId",g."homeTeamId")) v(team,opp) where g."seasonId"=20262027 and g.type=2 and g.game_schedule_state='OK' and g."startTime">'2026-11-23 10:05Z' and g.date between '2026-11-23' and '2026-12-24'), roster as(select r."teamId" team,r."playerId" pid,p.position='G' goalie, r.official_seen_at::date='2026-11-23' fresh from rosters r join players p on p.id=r."playerId" where r."seasonId"=20262027 and is_current), expected as(select s.*,r.pid,r.goalie,r.fresh from roster r join teamsched s using(team) where s.h<=10), lines as (select game_id,team_id team,opponent_team_id opp,player_id pid,'line' src,(proj_goals_es+proj_goals_pp+proj_goals_pk+proj_assists_es+proj_assists_pp+proj_assists_pk+proj_shots_es+proj_shots_pp+proj_shots_pk+proj_hits+proj_blocks is not null) core,(proj_pim is not null) extra from forge_player_projections join slate using(run_id) union all select game_id,team_id,opponent_team_id,player_id,case when player_class='goalie' then 'RG' else 'RS' end,case when player_class='goalie' then proj_saves+proj_shots_against+proj_goals_allowed+proj_shutout_prob is not null else proj_goals_es+proj_goals_pp+proj_assists_es+proj_assists_pp+proj_shots_es+proj_shots_pp+proj_hits+proj_blocks is not null end,false from forge_reserve_projections join slate using(run_id) union all select game_id,team_id,opponent_team_id,(c->>'goalie_id')::int,'candidate',(c->'if_starts' ?& array['saves','goals_allowed','shots_against','credited_win_prob','shutout_prob']) and (select count(*)=5 from jsonb_each(c->'if_starts') d where d.key in ('saves','goals_allowed','shots_against','credited_win_prob','shutout_prob') and jsonb_typeof(d.value)='number'),(c->'if_starts' ? 'toi_seconds') from forge_goalie_projections join slate using(run_id) cross join lateral jsonb_array_elements(uncertainty->'goalie_candidates'->'rows') c), k as(select game_id,team,opp,pid,bool_or(core) core,bool_or(core and extra) fullhead, bool_or(src='line') lineup,bool_or(src='candidate') cand,bool_or(src in ('RS','RG')) res,count(*) n from lines group by 1,2,3,4), c as(select e.*,k.core,k.fullhead,k.lineup,k.cand,k.res,k.n from expected e left join k using(game_id,team,opp,pid)) select team,max(games) game_ids,string_agg(format('%s:%s:%s:%s',pid,case when fresh then 'official' else 'other' end,case when goalie then 'G' else 'S' end,states),',' order by pid) membership from (select team,pid,goalie,fresh,string_agg(game_id::text,',' order by h) games,string_agg(case when lineup then 'L' when cand and res then 'B' when cand then 'C' when res then 'R' else '-' end,'' order by h) states from c group by 1,2,3,4) per_player group by team order by team;
